function leftLeafSum(root: TreeNode | null): number {
  if (!root) return 0;
  let total = 0;
  const queue: TreeNode[] = [root];
  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    const l = node.left;
    if (l) {
      if (!l.left && !l.right) total += l.val;
      else queue.push(l);
    }
    if (node.right) queue.push(node.right);
  }
  return total;
}

