        if not root:
            return 0
        total = 0
        queue = deque([root])
        while queue:
            node = queue.popleft()
            left = node.left
            if left:
                if not left.left and not left.right:
                    total += left.val
                else:
                    queue.append(left)
            if node.right:
                queue.append(node.right)
        return total

